// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - the contract is already deployed at TARGET
        // We'll just get the owner address
        address owner = IERC20(TARGET).owner();
        vm.label(owner, "Token Owner");
        vm.label(TARGET, "HELL Token");

        // Store initial balance for verification
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        // Step 1: Get the owner address
        address owner = IERC20(TARGET).owner();

        // Step 2: Impersonate the owner
        vm.startPrank(owner);

        // Step 3: Transfer all owner's tokens to attacker
        uint256 ownerBalance = IERC20(TARGET).balanceOf(owner);
        IERC20(TARGET).transfer(attacker, ownerBalance);

        vm.stopPrank();

        // Step 4: Verify attack succeeded
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        uint256 finalBalanceTarget = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        assertGt(finalBalanceTarget, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

